# owner: platform
"""Contact sheet for substitute teachers."""

from typing import List

from rosterkit.models import Student


def _check(students: List[Student]) -> None:
    if not students:
        raise ValueError("no students for contact sheet")
    for item in students:
        if not item.email:
            raise ValueError(f"no email: {item.display_name}")


def _pad(cells: List[tuple]) -> List[str]:
    widths = [max(len(cell) for cell in col) for col in zip(*cells)]
    return [
        "  ".join(c.ljust(w) for c, w in zip(row, widths)).rstrip()
        for row in cells
    ]


# ---
def contact_rows(students: List[Student]) -> List[str]:
    _check(students)
    ordered = sorted(students, key=lambda s: s.display_name)
    return _pad([
        (item.display_name, item.section, item.email)
        for item in ordered
    ])
