# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


def _stud(last, first, mail="a@x.test"):
    return Student("id", last, first, "7A", mail)


class ContactTests(unittest.TestCase):
    def test_sorted_and_aligned(self):
        rows = contact_rows([
            _stud("Zed", "Amy", "z@x.test"),
            _stud("Abel", "Bob", "b@x.test")
        ])
        self.assertTrue(rows[0].startswith("Abel, Bob"))
        self.assertEqual(rows[0].index("7A"), rows[1].index("7A"))
        self.assertEqual(rows[0].index("b@"), rows[1].index("z@"))

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ValueError, "Abel, Bob"):
            contact_rows([_stud("Abel", "Bob", None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])
